import { describe, expect, it } from "vitest";
import { as } from "./helpers.ts";

type Page = { data: unknown[]; next_cursor: string | null };

describe("/v1/notes (tenant-scoped)", () => {
  it("create + cursor list, scoped to the workspace", async () => {
    const owner = as("ws1", "owner");
    for (const title of ["note1", "note2"]) {
      expect((await owner("POST", "/v1/notes", { title, body: "content" })).status).toBe(201);
    }

    // Test cursor pagination
    const first = (await (await owner("GET", "/v1/notes?limit=1")).json()) as Page;
    expect(first.data).toHaveLength(1);

    const second = await (await owner("GET", `/v1/notes?limit=1&cursor=${first.next_cursor}`)).json();
    expect(second).toMatchObject({ data: [expect.any(Object)], next_cursor: null });

    // Test workspace isolation
    expect(((await (await as("ws2", "owner")("GET", "/v1/notes")).json()) as Page).data).toEqual([]);
  });

  it("get and delete operations", async () => {
    const owner = as("ws3", "owner");

    // Create a note
    const createRes = await owner("POST", "/v1/notes", { title: "test-note", body: "test body" });
    expect(createRes.status).toBe(201);
    const note = await createRes.json();

    // Get the note
    const getRes = await owner("GET", `/v1/notes/${note.id}`);
    expect(getRes.status).toBe(200);
    const fetchedNote = await getRes.json();
    expect(fetchedNote.title).toBe("test-note");
    expect(fetchedNote.body).toBe("test body");

    // Delete the note
    const deleteRes = await owner("DELETE", `/v1/notes/${note.id}`);
    expect(deleteRes.status).toBe(204);

    // Verify note is gone
    const getAfterDelete = await owner("GET", `/v1/notes/${note.id}`);
    expect(getAfterDelete.status).toBe(404);
  });

  it("titles are unique per workspace (409 on duplicate)", async () => {
    const owner = as("ws4", "owner");

    // First create should succeed
    const first = await owner("POST", "/v1/notes", { title: "unique-title", body: "body1" });
    expect(first.status).toBe(201);

    // Second create with same title should fail
    const second = await owner("POST", "/v1/notes", { title: "unique-title", body: "body2" });
    expect(second.status).toBe(409);
    expect(second.headers.get("Content-Type")).toBe("application/problem+json");
  });

  it("role-based access: viewers can read, members can create, only owners can delete", async () => {
    const viewer = as("ws5", "viewer");
    const member = as("ws5", "member");
    const owner = as("ws5", "owner");

    // Member can create
    const createRes = await member("POST", "/v1/notes", { title: "member-created", body: "body" });
    expect(createRes.status).toBe(201);
    const note = await createRes.json();

    // Viewer can read
    const viewerGet = await viewer("GET", `/v1/notes/${note.id}`);
    expect(viewerGet.status).toBe(200);

    const viewerList = await viewer("GET", "/v1/notes");
    expect(viewerList.status).toBe(200);

    // Viewer cannot create
    const viewerCreate = await viewer("POST", "/v1/notes", { title: "viewer-tries", body: "body" });
    expect(viewerCreate.status).toBe(403);

    // Member cannot delete (only owners can delete)
    const memberDelete = await member("DELETE", `/v1/notes/${note.id}`);
    expect(memberDelete.status).toBe(403);

    // Owner can delete
    const ownerDelete = await owner("DELETE", `/v1/notes/${note.id}`);
    expect(ownerDelete.status).toBe(204);
  });

  it("422 problem+json on bad body", async () => {
    const member = as("ws6", "member");

    // Empty title (min: 1)
    const emptyTitle = await member("POST", "/v1/notes", { title: "", body: "body" });
    expect(emptyTitle.status).toBe(422);
    expect(emptyTitle.headers.get("Content-Type")).toBe("application/problem+json");

    // Title too long (max: 200)
    const longTitle = await member("POST", "/v1/notes", { title: "a".repeat(201), body: "body" });
    expect(longTitle.status).toBe(422);
    expect(longTitle.headers.get("Content-Type")).toBe("application/problem+json");

    // Missing title
    const missingTitle = await member("POST", "/v1/notes", { body: "body" });
    expect(missingTitle.status).toBe(422);
    expect(missingTitle.headers.get("Content-Type")).toBe("application/problem+json");
  });

  it("Idempotency-Key replays the first response", async () => {
    const post = () => as("ws7", "owner")("POST", "/v1/notes", { title: "idempotent", body: "content" }, { "Idempotency-Key": "key1" });
    const a = await (await post()).json();
    const b = await post();
    expect(b.headers.get("Idempotent-Replayed")).toBe("true");
    expect(await b.json()).toEqual(a);
  });

  it("body field is optional", async () => {
    const owner = as("ws8", "owner");

    // Create without body
    const createRes = await owner("POST", "/v1/notes", { title: "no-body" });
    expect(createRes.status).toBe(201);
    const note = await createRes.json();
    expect(note.title).toBe("no-body");
    expect(note.body).toBe(null);

    // Create with body
    const createWithBody = await owner("POST", "/v1/notes", { title: "with-body", body: "some content" });
    expect(createWithBody.status).toBe(201);
    const noteWithBody = await createWithBody.json();
    expect(noteWithBody.title).toBe("with-body");
    expect(noteWithBody.body).toBe("some content");
  });
});

