16	  workspaceId: text("workspace_id").notNull(),
17	  name: text("name").notNull(),
18	});
19	
20	const Example = z.object({ id: z.string(), name: z.string() });
21	const ExampleCreate = z.object({ name: z.string().min(1).max(120) });
22	const toExample = (r: Pick<typeof examples.$inferSelect, "id" | "name">): z.infer<typeof Example> => ({ id: r.id, name: r.name });
23	
24	export const examplesRouter = new Hono<AppEnv>();
25	
26	examplesRouter.get("/", validate("query", cursorQuery), (c) => {
27	  const { cursor, limit } = c.req.valid("query");
28	  const after = decodeCursor(cursor);
29	  const rows = db
30	    .select({ id: examples.id, name: examples.name })
31	    .from(examples)
32	    .where(and(eq(examples.workspaceId, c.get("user").workspaceId), after ? gt(examples.id, after) : undefined))
33	    .orderBy(asc(examples.id))
34	    .limit(limit + 1)
35	    .all();
36	  const result = paginate(rows, limit);
37	  return respond(c, page(Example), { data: result.data.map(toExample), next_cursor: result.next_cursor });
38	});
39	
40	examplesRouter.post("/", requireRole("owner", "member"), idempotency(), validate("json", ExampleCreate), (c) => {
41	  const { name } = c.req.valid("json");
42	  const row = db
43	    .insert(examples)
44	    .values({ id: randomUUID(), workspaceId: c.get("user").workspaceId, name })
45	    .returning()
46	    .get();
47	  return respond(c, Example, toExample(row), 201);
48	});
